import type { Tools } from "../generated/tools";
import { isAuthChange } from "@flows/lib";

export default async function flow(
  input: { repository: string },
  tools: Tools
) {
  const prs = await tools.github.getNewPRs({ repo: input.repository });

  for (const pr of prs) {
    const files = await tools.github.getFiles({ pr });

    if (files.some(isAuthChange)) {
      await tools.slack.send({
        channel: "#security",
        message: `Security PR: ${pr.title}`
      });
    }
  }
}

import type { Tools } from "../generated/tools";
import { transitionIssue } from "@flows/lib";

export default async function flow(
  input: { issueKey: string },
  tools: Tools
) {
  const MAX_ATTEMPTS = 3;
  let attempt = 0;
  let issue: Issue | null = null;

  while (attempt < MAX_ATTEMPTS) {
    try {
      issue = await tools.jira.getIssue({ key: input.issueKey });
      await tools.jira.transitionIssue({ key: input.issueKey, status: "In Review" });
      return { delivered: true, movedTo: "In Review" };
    } catch (error) {
      attempt++;
      if (attempt >= MAX_ATTEMPTS) {
        await tools.slack.send({
          channel: "#ops",
          message: `Could not fetch Jira issue "${input.issueKey}" after ${MAX_ATTEMPTS} attempts. Error: ${(error as Error).message || "Unknown error"}`
        });
        return { delivered: false, reason: "Could not fetch issue after retries" };
      }
      await new Promise((resolve) => setTimeout(resolve, 1000));
    }
  }
}

