import type { Tools } from "../generated/tools";
import { formatDigest } from "@flows/lib";

export default async function flow(
  input: { repo: string; jql: string; email: string },
  tools: Tools
) {
  const [stats, issues, activity] = await Promise.all([
    tools.github.getRepoStats({ repo: input.repo }),
    tools.jira.searchIssues({ jql: input.jql }),
    tools.slack.getChannelActivity({ channel: "engineering" })
  ]);

  const digest = formatDigest(stats, issues, activity);

  await tools.email.send({
    to: input.email,
    subject: "Weekly Repository Digest",
    body: digest
  });

  return { delivered: true };
}

import type { Tools } from "../generated/tools";
import { severityOf } from "@flows/lib";

export default async function flow(
  input: { issueKey: string },
  tools: Tools
) {
  const issue = await tools.jira.getIssue({ key: input.issueKey });
  const severity = severityOf(issue);

  if (severity === "critical") {
    await tools.jira.createIssue({
      project: "OPS",
      summary: `Follow-up: ${issue.summary}`,
      description: `Follow-up issue for critical issue ${input.issueKey}.\n\n${issue.description}`,
    });
    await tools.slack.send({
      channel: "#incidents",
      message: `Critical issue detected: ${issue.summary} (${input.issueKey})`,
    });
  } else if (severity === "high") {
    await tools.slack.send({
      channel: "#engineering",
      message: `High severity issue: ${issue.summary} (${input.issueKey})`,
    });
  }

  return { severity };
}

import type { Tools } from "../generated/tools";

function formatError(error: unknown): string {
  return String(error);
}

export default async function flow(
  input: {
    releaseNote: string;
    onCallEmail: string;
  },
  tools: Tools
) {
  try {
    const slackMsg = await tools.slack.send({
      channel: "#releases",
      message: input.releaseNote
    });
    await tools.slack.send({
      channel: "#audit",
      message: "Release note sent to #releases"
    });
    return { delivered: true, slackMsg };
  } catch (error) {
    const alertBody = formatError(error);
    await tools.email.send({
      to: input.onCallEmail,
      subject: "Release Note Delivery Failure",
      body: alertBody
    });
    await tools.slack.send({
      channel: "#audit",
      message: "Release note failed to send to #releases"
    });
    return { delivered: false };
  }
}

import type { Tools } from "../generated/tools";

export default async function flow(input: { repository: string }, tools: Tools) {
  const prs = await tools.github.getNewPRs({ repo: input.repository });

  let commentsPosted = 0;

  for (const pr of prs) {
    if (pr.title.startsWith("WIP")) {
      continue;
    }

    await tools.github.addComment({ pr, body: "Queued for review" });
    commentsPosted += 1;

    if (commentsPosted >= 5) {
      break;
    }
  }

  return { posted: commentsPosted };
}
